MOD = 10**9+7
from functools import lru_cache

def numOfArrays(n, m, k):
    @lru_cache(None)
    def dp(pos, curr_max, curr_k):
        if pos == n:
            return 1 if curr_k == k else 0
        ans = 0
        for num in range(1, m+1):
            if num > curr_max:
                if curr_k + 1 <= k:
                    ans = (ans + dp(pos+1, num, curr_k+1)) % MOD
            else:
                ans = (ans + dp(pos+1, curr_max, curr_k)) % MOD
        return ans
    return dp(0, 0, 0)
